<script lang="ts" setup>
import { Card } from "ant-design-vue";
import { Icon } from "@/components/Icon";
import { useGo } from "@/hooks/web/usePage";
import { onMounted, ref } from "vue";
import { getUserInfo } from "@/api/base/user";

import { notification } from "ant-design-vue";

const go = useGo();

const [notificationApi, contextHolder] = notification.useNotification();

const handleClick = (path: string, id: number) => {
  if (id === 6) {
    notificationApi.info({
      message: `AI解读`,
      description: "正在开发中，敬请期待...",
      duration: 2,
     
    });
    return;
  } else {
    go(path);
  }
};

const navItems = ref<NavItem[]>([
  {
    id: 1,
    title: "创建分析",
    icon: "ant-design:file-add-outlined",
    path: "/lims/analysis-task/0/0",
  },
  {
    id: 2,
    title: "重建分析",
    icon: "ant-design:file-sync-outlined",
    path: "/lims/analysis-task",
  },
  {
    id: 3,
    title: "报告审核",
    icon: "ant-design:file-search-outlined",
    path: "/analysis-report",
  },
  {
    id: 4,
    title: "模板修改",
    icon: "ant-design:profile-outlined",
    path: "/system/template",
  },
  {
    id: 5,
    title: "下载报告",
    icon: "ant-design:vertical-align-bottom-outline",
    path: "/analysis-report",
  },
  {
    id: 6,
    title: "AI解读",
    icon: "ant-design:global-outlined",
    path: "",
  },
]);
onMounted(async () => {
  if (await isTemplateMenu()) {
    navItems.value = navItems.value.filter((item) => item.id !== 4);
  }
});

// 判断是否存在模板修改菜单
async function isTemplateMenu() {
  const res = await getUserInfo();

  const systemMenus = res.menus.filter((item) => item.path === "/system");

  if (systemMenus.length > 0) {
    const children =
      systemMenus
        .map((item) => {
          return item.children;
        })
        .flat() || [];

    const templateMenu = children.filter(
      (item) => item && item.path === "/system/template"
    );

    if (templateMenu.length <= 0) {
      return true;
    }
  }
  return false;
}
</script>

